SELECT DATE_TRUNC('MONTH', shipped_date) AS activity_month, DATE_TRUNC('YEAR', shipped_date) AS year_start, COUNT(CASE WHEN carrier = 'DHL' THEN 1 END) AS dhl_count, COUNT(DISTINCT id) AS distinct_ids, COUNT(CASE WHEN carrier = 'UPS' THEN 1 END) AS ups_count FROM shipments GROUP BY GROUPING SETS ((DATE_TRUNC('MONTH', shipped_date), DATE_TRUNC('YEAR', shipped_date)), (DATE_TRUNC('MONTH', shipped_date)))
